    this.style.display = 'grid';
    this.style.gridTemplateColumns = 'repeat(7, minmax(0, 1fr))';
    this.style.gap = gapVal;
    this.style.width = '100%';
    this.style.alignItems = 'center';
    this.style.justifyContent = 'center';

